const { Document, Packer, Paragraph, TextRun, AlignmentType, HeadingLevel } = require('docx');
const fs = require('fs');

// 创建文章内容
const title = "春天的美好";
const paragraphs = [
    "春风轻拂，万物苏醒。当第一缕和煦的阳光透过枯枝，嫩绿的新芽便悄然探出头来，像是大自然的微笑，轻柔地唤醒沉睡的世界。田野间，金黄的油菜花随风摇曳，与蓝天白云交相辉映，绘就一幅生机勃勃的画卷。",
    "春天的气息是甜美的，带着泥土的芬芳和花朵的幽香。漫步在幽静的小径上，微风拂面，仿佛能听见花瓣绽放的声音。那清脆的鸟鸣，是春天的交响乐，每一个音符都充满了欢愉与希望。远处的小溪潺潺流淌，映照着碧绿的垂柳，宛如一幅流动的水墨画。",
    "春天不仅仅是季节的轮回，更是心灵的慰藉。它告诉我们，无论经历了多么漫长的寒冬，生命终将迎来温暖的春天。每一朵花开都是一个承诺，每一片新绿都是一个希望的种子。春天，以它独特的方式，教会我们相信美好的力量，拥抱生命的奇迹。",
    "在这充满诗意的季节里，让我们心怀感激，感受大自然的馈赠，怀揣希望，勇敢前行。春天的美好，不仅在于眼前的景致，更在于它给予我们重新开始的勇气与信心。"
];

// 创建文档
const doc = new Document({
    styles: {
        default: {
            document: {
                run: { font: "Microsoft YaHei", size: 24 } // 12pt
            }
        },
        paragraphStyles: [
            {
                id: "Title",
                name: "Title",
                basedOn: "Normal",
                run: { size: 48, bold: true, font: "Microsoft YaHei", color: "2E75B6" },
                paragraph: { spacing: { before: 400, after: 400 }, alignment: AlignmentType.CENTER }
            }
        ]
    },
    sections: [{
        properties: {
            page: {
                margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
            }
        },
        children: [
            // 标题
            new Paragraph({
                heading: HeadingLevel.TITLE,
                children: [new TextRun({ text: title, bold: true, size: 48, font: "Microsoft YaHei" })],
                alignment: AlignmentType.CENTER,
                spacing: { before: 400, after: 600 }
            }),
            // 正文段落
            ...paragraphs.map((text, index) => 
                new Paragraph({
                    children: [new TextRun({ text: text, size: 24, font: "Microsoft YaHei" })],
                    alignment: AlignmentType.JUSTIFIED,
                    spacing: { before: 200, after: 200, line: 360 },
                    indent: { firstLine: 480 }
                })
            )
        ]
    }]
});

// 保存文档
const outputPath = 'G:\\MOMA\\llm-host-claw\\tests\\userspace\\sessions\\5f9b6e51-68d6-4857-a1ea-62e4cb9be2da\\runs\\spring_essay.docx';
Packer.toBuffer(doc).then(buffer => {
    fs.writeFileSync(outputPath, buffer);
    console.log('Word文档已成功创建: ' + outputPath);
});

